struct Particle { x: f32, y: f32, vx: f32, vy: f32 }
let mut pool: Vec<Particle> = Vec::with_capacity(max);
pool.push(Particle { x: 0.0, y: 0.0, vx: 1.0, vy: 0.0 });
for p in pool.iter_mut() {            // contiguous, one bounds check for the slice
    p.x += p.vx * dt;
    p.y += p.vy * dt;
}
